const json=(v,status=200)=>Response.json(v,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'}});
const fail=(status,message)=>{throw Object.assign(new Error(message),{status})};
const now=()=>Date.now(),id=()=>crypto.randomUUID();
const digest=async s=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))].map(x=>x.toString(16).padStart(2,'0')).join('');
const token=()=>[...crypto.getRandomValues(new Uint8Array(32))].map(x=>x.toString(16).padStart(2,'0')).join('');
const text=(v,max,required=true)=>{if(typeof v!=='string'||v.trim().length>max||required&&!v.trim())fail(400,'Please check the required fields.');return v.trim()};
const email=v=>{const s=text(v,254).toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s))fail(400,'Please enter a valid email.');return s;};
const safeInt=(n,min,max)=>{if(!Number.isSafeInteger(n)||n<min||n>max)fail(400,'Invalid number.');return n;};
async function body(r){if(Number(r.headers.get('content-length'))>18000)fail(413,'Request too large.');const s=await r.text();if(s.length>18000)fail(413,'Request too large.');try{return JSON.parse(s)}catch{fail(400,'Invalid request.')}}
function sql(db,s,...args){return db.prepare(s).bind(...args)}
function audit(db,actor,action,entity){return sql(db,'INSERT INTO events VALUES (?,?,?,?,?)',id(),actor,action,entity,now())}
async function staff(r,env){const uid=r.headers.get('oai-authenticated-user-id'),mail=r.headers.get('oai-authenticated-user-email')?.toLowerCase();if(!uid||!mail)fail(401,'Sign in to continue.');let m=await sql(env.DB,'SELECT * FROM members WHERE user_id=?',uid).first();
 if(!m){const invited=await sql(env.DB,'SELECT * FROM members WHERE email=? AND active=1',mail).first();const isOwner=mail===env.OWNER_EMAIL?.toLowerCase();if(!invited&&!isOwner)fail(403,'Your account has not been authorized.');if(invited?.user_id&&invited.user_id!==uid)fail(403,'Account identity mismatch.');if(invited){await sql(env.DB,'UPDATE members SET user_id=? WHERE email=? AND user_id IS NULL',uid,mail).run();}else{await sql(env.DB,'INSERT OR IGNORE INTO members VALUES (?,?,?,?,?)',mail,uid,'admin',1,now()).run();}m=await sql(env.DB,'SELECT * FROM members WHERE user_id=?',uid).first();}
 if(!m||!m.active)fail(403,'Your account has not been authorized.');return m;}
async function throttle(r,env){const key=await digest((r.headers.get('cf-connecting-ip')||'unknown')+':'+Math.floor(now()/3600000));await sql(env.DB,'INSERT INTO rate_limits VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET count=count+1',key,now()+7200000).run();const v=await sql(env.DB,'SELECT count FROM rate_limits WHERE key=?',key).first();if(v.count>12)fail(429,'Too many requests. Please try again later.');await sql(env.DB,'DELETE FROM rate_limits WHERE expires_at<?',now()).run();}
async function customerQuote(r,env){const t=r.headers.get('x-quote-token');if(!t||!/^[a-f0-9]{64}$/.test(t))fail(404,'Quote not found.');const q=await sql(env.DB,'SELECT * FROM quotes WHERE token_hash=?',await digest(t)).first();if(!q||!['issued','accepted'].includes(q.status))fail(404,'Quote not found.');if(q.status==='issued'&&q.expires_at<now())fail(410,'This quote has expired. Please contact your travel designer.');return q;}
async function handle(r,env){try{if(!env.DB)fail(503,'Service is being configured. Please try again later.');const path=new URL(r.url).pathname.replace(/\/$/,'');if(r.method==='POST'){const origin=r.headers.get('origin');if(!origin||origin!==new URL(r.url).origin)fail(403,'Invalid request origin.');if(!r.headers.get('content-type')?.includes('application/json'))fail(415,'JSON required.');}
 if(path==='/api/inquiries'&&r.method==='POST'){const b=await body(r);if(b.website)fail(400,'Unable to accept this request.');if(b.consent!==true)fail(400,'Please agree to the privacy notice.');const n=text(b.name,100),e=email(b.email);if(!['private','rail','cruise'].includes(b.type))fail(400,'Invalid inquiry type.');safeInt(b.adults,1,50);safeInt(b.children,0,20);safeInt(b.days,1,90);const payload={type:b.type,adults:b.adults,children:b.children,days:b.days};for(const k of ['destination','interest','date','flexibility','ages','hotel','pace','country','whatsapp','notes','railRoute','railCabin','railExtension','cruiseDirection','cruiseStyle','cruiseDuration','cruiseCabin','cruiseExtension','budget']){payload[k]=text(b[k]??'',k==='notes'?3000:250,false);}await throttle(r,env);if(typeof b.requestId!=='string'||!/^\w{8}-\w{4}-\w{4}-\w{4}-\w{12}$/.test(b.requestId))fail(400,'Invalid request identifier.');const ref='INQ-'+b.requestId.toUpperCase();if(await sql(env.DB,'SELECT id FROM inquiries WHERE id=?',ref).first())return json({reference:ref,saved:true,emailSent:false});const t=now();await env.DB.batch([sql(env.DB,'INSERT INTO inquiries VALUES (?,?,?,?,?,?,?,?)',ref,n,e,JSON.stringify(payload),'new',null,t,t),sql(env.DB,'INSERT INTO notifications VALUES (?,?,?,?,?)',id(),ref,env.INQUIRY_EMAIL||'1279567059@qq.com','awaiting_email_setup',t)]);return json({reference:ref,saved:true,emailSent:false},201);}
 if(path==='/api/quote'&&r.method==='GET'){const q=await customerQuote(r,env);const {token_hash,inquiry_id,author,...view}=q;return json({quote:view});}
 if(path==='/api/quote/accept'&&r.method==='POST'){const q=await customerQuote(r,env);const b=await body(r);if(b.accept!==true)fail(400,'Please confirm acceptance.');if(q.status==='accepted')return json({status:'accepted',paymentStatus:'unpaid',reference:q.id});await env.DB.batch([sql(env.DB,"UPDATE quotes SET status='accepted',accepted_at=? WHERE id=? AND status='issued' AND expires_at>=?",now(),q.id,now()),audit(env.DB,'customer-link','quote_accepted',q.id)]);const state=await sql(env.DB,'SELECT status FROM quotes WHERE id=?',q.id).first();if(state.status!=='accepted')fail(409,'This quote is no longer available.');return json({status:'accepted',paymentStatus:'unpaid',reference:q.id});}
 if(!path.startsWith('/api/admin'))fail(404,'Not found.');const user=await staff(r,env);
 if(path==='/api/admin/me')return json({user:{email:user.email,role:user.role},notificationEmail:env.INQUIRY_EMAIL||'1279567059@qq.com',emailReady:false});
 if(path==='/api/admin/inquiries'&&r.method==='GET'){const rows=await sql(env.DB,'SELECT id,name,email,status,assigned_to,created_at FROM inquiries ORDER BY created_at DESC LIMIT 200').all();return json({inquiries:rows.results});}
 if(path==='/api/admin/inquiry'&&r.method==='GET'){const ref=new URL(r.url).searchParams.get('id');const inquiry=await sql(env.DB,'SELECT * FROM inquiries WHERE id=?',ref).first();if(!inquiry)fail(404,'Inquiry not found.');const [notes,quotes]=await Promise.all([sql(env.DB,'SELECT * FROM notes WHERE inquiry_id=? ORDER BY created_at',ref).all(),sql(env.DB,'SELECT id,title,currency,amount,details,inclusions,exclusions,terms,expires_at,status,author,created_at,accepted_at FROM quotes WHERE inquiry_id=? ORDER BY created_at DESC',ref).all()]);return json({inquiry:{...inquiry,payload:JSON.parse(inquiry.payload)},notes:notes.results,quotes:quotes.results});}
 if(path==='/api/admin/inquiry'&&r.method==='POST'){const b=await body(r);if(!['new','contacted','quoting','closed'].includes(b.status))fail(400,'Invalid status.');const ref=text(b.id,80);const found=await sql(env.DB,'SELECT id FROM inquiries WHERE id=?',ref).first();if(!found)fail(404,'Inquiry not found.');const assigned=b.assignToMe?user.email:null;await env.DB.batch([sql(env.DB,'UPDATE inquiries SET status=?,assigned_to=COALESCE(?,assigned_to),updated_at=? WHERE id=?',b.status,assigned,now(),ref),audit(env.DB,user.email,'inquiry_updated',ref)]);return json({ok:true});}
 if(path==='/api/admin/note'&&r.method==='POST'){const b=await body(r),ref=text(b.inquiryId,80),note=text(b.body,3000);if(!await sql(env.DB,'SELECT id FROM inquiries WHERE id=?',ref).first())fail(404,'Inquiry not found.');await env.DB.batch([sql(env.DB,'INSERT INTO notes VALUES (?,?,?,?,?)',id(),ref,user.email,note,now()),audit(env.DB,user.email,'note_added',ref)]);return json({ok:true});}
 if(path==='/api/admin/quotes'&&r.method==='POST'){const b=await body(r);if(!['CNY','USD'].includes(b.currency))fail(400,'Choose CNY or USD.');const amount=safeInt(b.amount,1,10000000000),expiry=safeInt(b.expiresAt,now()+60000,now()+366*86400000);const ref=text(b.inquiryId,80);if(!await sql(env.DB,'SELECT id FROM inquiries WHERE id=?',ref).first())fail(404,'Inquiry not found.');const qid='QUO-'+id().toUpperCase();await env.DB.batch([sql(env.DB,'INSERT INTO quotes VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',qid,ref,text(b.title,160),b.currency,amount,text(b.details,7000),text(b.inclusions,2000),text(b.exclusions,2000),text(b.terms,4000),expiry,'draft',null,user.email,now(),null),audit(env.DB,user.email,'quote_created',qid)]);return json({id:qid},201);}
 if(path==='/api/admin/quote/issue'&&r.method==='POST'){const b=await body(r),qid=text(b.id,80);const q=await sql(env.DB,'SELECT * FROM quotes WHERE id=?',qid).first();if(!q||q.status!=='draft'||q.expires_at<now())fail(409,'Only a valid draft can be issued.');const t=token();const result=await sql(env.DB,"UPDATE quotes SET status='issued',token_hash=? WHERE id=? AND status='draft'",await digest(t),qid).run();if(!result.meta.changes)fail(409,'Quote already issued.');await audit(env.DB,user.email,'quote_issued',qid).run();return json({link:new URL('/quote/',r.url).href+'#'+t,emailSent:false});}
 if(path==='/api/admin/quote/revoke'&&r.method==='POST'){const b=await body(r);await env.DB.batch([sql(env.DB,"UPDATE quotes SET status='revoked',token_hash=NULL WHERE id=? AND status IN ('draft','issued')",text(b.id,80)),audit(env.DB,user.email,'quote_revoked',b.id)]);return json({ok:true});}
 if(path==='/api/admin/team'){if(user.role!=='admin')fail(403,'Administrator access required.');if(r.method==='GET')return json({members:(await sql(env.DB,'SELECT email,role,active,created_at FROM members').all()).results});const b=await body(r),e=email(b.email);if(e===user.email||e===env.OWNER_EMAIL?.toLowerCase())fail(400,'The owner account cannot be changed here.');if(!['admin','staff'].includes(b.role))fail(400,'Invalid role.');await env.DB.batch([sql(env.DB,'INSERT INTO members VALUES (?,NULL,?,?,?) ON CONFLICT(email) DO UPDATE SET role=excluded.role,active=excluded.active',e,b.role,b.active?1:0,now()),audit(env.DB,user.email,b.active?'team_authorized':'team_disabled',e)]);return json({ok:true,invitationSent:false});}
 fail(404,'Not found.');}catch(e){if(e.status)return json({error:e.message},e.status);console.error('CRM request failed');return json({error:'Unable to complete this request. Please try again.'},500);}}

