export default {async fetch(request,env){const url=new URL(request.url);if(['/payment','/payment/','/plan-my-trip','/plan-my-trip/'].includes(url.pathname))return Response.redirect(url.origin+'/#request-quote',302);if(url.pathname==='/api/inquiries'&&request.method==='POST')return new Response('Inquiries are not available yet',{status:503});if(url.pathname.startsWith('/api/'))return handle(request,env);if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});let p=url.pathname;if(!p.split('/').pop().includes('.'))p=p.replace(/\/$/,'')+'/index.html';const asset=ASSETS[p];if(!asset)return new Response('Page not found',{status:404});const bytes=Uint8Array.from(atob(asset[1]),c=>c.charCodeAt(0));return new Response(request.method==='HEAD'?null:bytes,{headers:{'Content-Type':asset[0],'Cache-Control':p.endsWith('.html')?'no-store':'public, max-age=300','Referrer-Policy':'no-referrer','X-Content-Type-Options':'nosniff','X-Frame-Options':'SAMEORIGIN'}});}};
